import threading
from concurrent.futures import Future, ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Run check on every element of xs in parallel using a thread pool.

    Returns the checked values in input order. If any element is bad,
    raises the Bad of the lowest-index bad element, regardless of which
    thread finishes first.
    """
    if not xs:
        return []
    with ThreadPoolExecutor(max_workers=len(xs)) as ex:
        futures: list[Future[int]] = [ex.submit(check, x) for x in xs]
        out: list[int] = []
        try:
            # Collect in index order: the first future that raises is the
            # lowest-index bad element, independent of completion order.
            for fut in futures:
                out.append(fut.result())
        except Bad:
            for fut in futures:
                fut.cancel()
            raise
    return out


def test_all_even_returns_values_in_order() -> None:
    assert all_even([2, 4, 6, 8, 10]) == [2, 4, 6, 8, 10]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_single_bad_element() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 4, 7, 8])
    assert ei.value.n == 7


def test_lowest_index_bad_wins_among_many() -> None:
    for _ in range(20):
        with pytest.raises(Bad) as ei:
            all_even([2, 9, 4, 3, 1, 6, 5])
        assert ei.value.n == 9


def test_lowest_index_wins_even_if_later_bad_finishes_first(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    later_raised = threading.Event()

    def slow_check(x: int) -> int:
        if x == 5:
            later_raised.set()
            raise Bad(5)
        if x == 3:
            # Earlier bad element only finishes after the later one has raised.
            later_raised.wait(timeout=2.0)
            raise Bad(3)
        return x

    monkeypatch.setitem(globals(), "check", slow_check)
    with pytest.raises(Bad) as ei:
        all_even([2, 3, 4, 5])
    assert ei.value.n == 3


def test_bad_value_is_index_based_not_value_based() -> None:
    with pytest.raises(Bad) as ei:
        all_even([4, 11, 3, 1])
    assert ei.value.n == 11
